3	// Regression coverage for health queries over disconnected-and-replayed
4	// telemetry. A node may hold heartbeats whose seqs have gaps and whose arrival
5	// order disagrees with both seq order and collection-time order: a record
6	// buffered during an outage can arrive late, a smaller seq can arrive after a
7	// larger one, and the same record can be re-submitted at an even later receive
8	// time. These tests pin the query contract:
9	//
10	//   - "latest telemetry" is strictly the record with the greatest seq, never
11	//     the most recently received one or the one with the newest collection
12	//     time; every displayed field (time, version, height, cumulative missed)
13	//     comes from that one record and fields are never spliced across records;
14	//   - replaying an older, smaller-seq record at a later receive time neither
15	//     refreshes the latest collection time nor flips any judgement;
16	//   - the online boundary is exact at sub-second precision: age == 60s stays
17	//     online, age == 60s + 1 nanosecond is offline, independently of the
18	//     whole-second time the terminal happens to print, and independently of
19	//     the timezone spelling of the instants;
20	//   - a baseline query obeys the same latest-record selection and online time
21	//     rule — the baseline only changes the quantity used by the missed-duty
22	//     alarm;
23	//   - a query time earlier than the greatest-seq record's collection time is
24	//     an error for both plain and baseline queries, even when a smaller-seq
25	//     record had already been collected by then, and no query or query failure
26	//     rewrites saved heartbeats.
27	
28	import (
29		"os"
30		"strings"
31		"testing"
32		"time"
33	)
34	
35	// mustParseRFC3339 parses a fixed test instant, failing the test rather than
36	// returning the zero time. Fractional seconds and explicit offsets are part of
37	// the input on purpose.
38	func mustParseRFC3339(t *testing.T, s string) time.Time {
39		t.Helper()
40		parsed, err := time.Parse(time.RFC3339, s)
41		if err != nil {
42			t.Fatalf("test setup: parse %q: %v", s, err)
43		}
44		return parsed
45	}
46	
47	// reconnectFixture is the disordered-history scenario: the greater-seq
48	// record was collected two minutes before the query (stale, offline), while
49	// the smaller-seq record was collected only ten seconds before the query
50	// (fresh). They also disagree on version, height and cumulative missed.
51	type reconnectFixture struct {
52		query     time.Time
53		bigSeq    Heartbeat // seq 10, collected 2 minutes ago
54		smallSeq  Heartbeat // seq 5, collected 10 seconds ago
55		latestAge time.Duration
56		freshAge  time.Duration
57	}
58	
59	func newReconnectFixture(t *testing.T) reconnectFixture {
60		t.Helper()
61		q := testBase
62		return reconnectFixture{
63			query:     q,
64			latestAge: 2 * time.Minute,
65			freshAge:  10 * time.Second,
66			bigSeq:    hb("recon", 10, q.Add(-2*time.Minute), "1.25.0", 1000, 5),
67			smallSeq:  hb("recon", 5, q.Add(-10*time.Second), "1.26.0", 900, 2),
68		}
69	}
70	
71	// assertHealthUsesBigSeq verifies a health result is derived entirely from the
72	// seq-10 record: offline because of its two-minute-old collection time, with
73	// its version, height and cumulative missed. A selector that instead picked
74	// the fresh seq-5 record (by receive order or newest collection time) would
75	// report online with version 1.26.0, height 900 and missed 2, and a selector
76	// that spliced fields would mismatch one of these.
77	func (f reconnectFixture) assertHealthUsesBigSeq(t *testing.T, r HealthResult) {
78		t.Helper()
79		if r.Seq != f.bigSeq.Seq {
80			t.Errorf("latest seq = %d, want %d (greatest seq, not freshest collection)", r.Seq, f.bigSeq.Seq)
81		}
82		if r.Status != "offline" {
83			t.Errorf("status = %q, want offline: the greatest-seq record is 2 minutes old; the fresh seq-%d record must not make the node online", r.Status, f.smallSeq.Seq)
84		}
85		if !r.CollectedAt.Equal(f.bigSeq.CollectedAt) {
86			t.Errorf("collected_at = %v, want %v (from seq %d, not the newer collection of seq %d)",
87				r.CollectedAt, f.bigSeq.CollectedAt, f.bigSeq.Seq, f.smallSeq.Seq)
88		}
89		if r.Version != f.bigSeq.Version {
90			t.Errorf("version = %q, want %q from seq %d; fields must not be spliced", r.Version, f.bigSeq.Version, f.bigSeq.Seq)
91		}
92		if r.Height != f.bigSeq.Height {
93			t.Errorf("height = %d, want %d from seq %d", r.Height, f.bigSeq.Height, f.bigSeq.Seq)
94		}
95		if r.Missed != f.bigSeq.Missed {
96			t.Errorf("cumulative missed = %d, want %d from seq %d", r.Missed, f.bigSeq.Missed, f.bigSeq.Seq)
97		}
98		joined := strings.Join(r.Findings, ";")
99		if !strings.Contains(joined, "offline") {
100			t.Errorf("findings %v must contain offline", r.Findings)
101		}
102		if !strings.Contains(joined, "version skew: 1.25.0 != 1.26.0") {
103			t.Errorf("findings %v must judge version skew from seq %d (1.25.0); the fresh seq-%d record's 1.26.0 must not mask it", r.Findings, f.bigSeq.Seq, f.smallSeq.Seq)
104		}
105	}
